/**
 * Identitas perangkat & lokasi GPS untuk absensi (clock in / clock out).
 *
 * App ini dibungkus Capacitor, tapi proyek web TIDAK memasang paket @capacitor/*
 * (plugin diakses lewat global `window.Capacitor` yang disuntik runtime native —
 * pola yang sama dipakai push.js & nativeBack.js). Karena itu kedua helper di
 * bawah memakai DETEKSI RUNTIME:
 *   - native  → plugin Capacitor (Device / Geolocation) bila tersedia
 *   - browser → API web standar sebagai fallback
 * Sehingga fitur ini tetap jalan saat dev di browser maupun setelah jadi APK.
 */

const DEVICE_KEY = 'juragan.device_id'

function uuid() {
	if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID()
	return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
		const r = (Math.random() * 16) | 0
		const v = c === 'x' ? r : (r & 0x3) | 0x8
		return v.toString(16)
	})
}

/**
 * ID perangkat yang stabil.
 * Native: identifier asli dari plugin Device.
 * Browser: UUID yang dibuat sekali lalu disimpan di localStorage perangkat itu.
 */
export async function getDeviceId() {
	const Device = window.Capacitor?.Plugins?.Device
	if (Device?.getId) {
		try {
			const res = await Device.getId()
			const id = res?.identifier || res?.uuid
			if (id) return String(id)
		} catch (e) {
			// plugin ada tapi gagal → pakai fallback di bawah
		}
	}

	let id = null
	try {
		id = localStorage.getItem(DEVICE_KEY)
		if (!id) {
			id = `web-${uuid()}`
			localStorage.setItem(DEVICE_KEY, id)
		}
	} catch (e) {
		// localStorage diblokir (mode privat) → ID sementara, tetap terisi
		id = `tmp-${uuid()}`
	}
	return id
}

function pesanGeoError(err) {
	// Kode standar Geolocation API: 1=PERMISSION_DENIED, 2=POSITION_UNAVAILABLE, 3=TIMEOUT
	if (err?.code === 1)
		return 'Izin lokasi ditolak. Aktifkan izin lokasi untuk aplikasi ini, lalu coba lagi.'
	if (err?.code === 2)
		return 'Lokasi tidak dapat ditentukan. Pastikan GPS menyala dan Anda tidak di area tertutup.'
	if (err?.code === 3) return 'Pencarian lokasi terlalu lama. Coba lagi di tempat terbuka.'
	return err?.message || 'Gagal membaca lokasi perangkat.'
}

/** Koordinat perangkat saat ini → { latitude, longitude }. Melempar error yang ramah. */
export async function getPosition() {
	const Geo = window.Capacitor?.Plugins?.Geolocation
	if (Geo?.getCurrentPosition) {
		try {
			const pos = await Geo.getCurrentPosition({
				enableHighAccuracy: true,
				timeout: 15000,
			})
			return {
				latitude: pos?.coords?.latitude,
				longitude: pos?.coords?.longitude,
			}
		} catch (e) {
			throw new Error(pesanGeoError(e))
		}
	}

	if (!navigator.geolocation) {
		throw new Error('Perangkat ini tidak mendukung pembacaan lokasi (GPS).')
	}

	return new Promise((resolve, reject) => {
		navigator.geolocation.getCurrentPosition(
			(pos) => resolve({ latitude: pos.coords.latitude, longitude: pos.coords.longitude }),
			(err) => reject(new Error(pesanGeoError(err))),
			{ enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
		)
	})
}
