/* ===== Absensi (kartu Clock in di greeting card) =====
 *
 * Karyawan TIDAK dikirim dari sini: backend menurunkannya dari user yang login
 * lewat Master Karyawan.user_id, supaya seseorang tidak bisa mengabsenkan orang
 * lain. Klien hanya mengirim lokasi GPS + ID perangkat.
 */
const absensiRes = createResource({
	url: 'juragan.api.portal.absensi.get_status_absensi',
	method: 'GET',
	auto: true,
})
const absensi = computed(() => absensiRes.data || null)
// Log terakhir hari ini = IN → sedang bekerja, tombol berubah jadi "Clock out".
const sedangMasuk = computed(() => !!absensi.value?.sedang_masuk)
// Akun belum ditautkan ke Master Karyawan → tombol dinonaktifkan.
const belumTertaut = computed(() => absensi.value?.tertaut === false)
// Absen lewat aplikasi dibatasi peran (CMO & Field Coll) — server yang menentukan,
// ini hanya cerminannya. State awal sengaja dianggap boleh supaya tombol tidak
// berkedip mati sebelum datanya termuat.
const bolehAbsen = computed(() => absensi.value?.boleh_absen !== false)
// Jendela absen (Pengaturan HR): clock in buka sejak Jam Masuk − "Mulai
// Check-in Sebelum Jam Masuk", clock out tutup di Jam Pulang + "Izinkan
// Check-out Setelah Jam Pulang". Backend mengirim boleh_*=true bila tidak
// dibatasi, jadi state awal (data belum termuat) sengaja dianggap boleh supaya
// tombol tidak berkedip mati. Masing-masing hanya berlaku di gilirannya:
// batas clock out tidak boleh mengunci orang yang belum clock in, dan
// sebaliknya.
const belumWaktunya = computed(() => !sedangMasuk.value && absensi.value?.boleh_clock_in === false)
const lewatWaktunya = computed(() => sedangMasuk.value && absensi.value?.boleh_clock_out === false)
const diLuarJendela = computed(() => belumWaktunya.value || lewatWaktunya.value)

// "2026-08-03 08:00:00" → "08:00"
function jam(dt) {
	return dt ? String(dt).slice(11, 16) : ''
}

const absensiText = computed(() => {
	const a = absensi.value
	if (!a) return "You haven't clocked in today."
	if (a.boleh_absen === false) return 'Absen lewat aplikasi hanya untuk CMO dan Field Coll.'
	if (a.tertaut === false) return 'Akun Anda belum terhubung ke data karyawan.'
	if (a.sedang_masuk && lewatWaktunya.value)
		return `Clock in ${jam(a.waktu_masuk)} · Clock out ditutup pukul ${a.clock_out_sampai}.`
	if (a.sedang_masuk) return `Clock in pukul ${jam(a.waktu_masuk)}.`
	if (a.waktu_keluar) {
		const ringkas = `Clock in ${jam(a.waktu_masuk)} · Clock out ${jam(a.waktu_keluar)}.`
		// Sesi hari ini sudah tutup — beri tahu kapan tombolnya hidup lagi.
		return a.clock_in_berikutnya
			? `${ringkas} Absen berikutnya ${a.clock_in_berikutnya}.`
			: ringkas
	}
	if (belumWaktunya.value) return `Clock in dibuka pukul ${a.clock_in_mulai}.`
	return "You haven't clocked in today."
})

const clockInRes = createResource({
	url: 'juragan.api.portal.absensi.clock_in',
	method: 'POST',
})
const clockOutRes = createResource({
	url: 'juragan.api.portal.absensi.clock_out',
	method: 'POST',
})

const sedangAbsen = ref(false)
async function absen() {
	if (sedangAbsen.value || belumTertaut.value || diLuarJendela.value || !bolehAbsen.value) return
	sedangAbsen.value = true
	try {
		// Lokasi dibaca DULU: bila izin GPS ditolak, tidak ada log yang tercatat
		// setengah jadi — backend juga menolak bila lat/long kosong.
		const pos = await getPosition()
		const payload = {
			latitude: pos.latitude,
			longitude: pos.longitude,
			id_perangkat: await getDeviceId(),
		}
		if (sedangMasuk.value) {
			await clockOutRes.submit(payload)
			notifySuccess('Clock out tercatat.')
		} else {
			await clockInRes.submit(payload)
			notifySuccess('Clock in tercatat.')
		}
		await absensiRes.reload()
	} catch (e) {
		notifyError(e, 'Gagal mencatat absensi')
	} finally {
		sedangAbsen.value = false
	}
}

