	return [...base, M_INVOICE_MOTOR]
}

// Role Director → tambahan tile Master Data Nasabah & Target dan Realisasi
// (tile tunggal, tanpa varian Done/Partial/dll). Non-destruktif: hanya menambah
// bila belum ada. Administrator memiliki role Director via frappe.get_roles.
function withDirectorExtras(base) {
	if (!roles.value.includes('Director')) return base
	const extra = []
	if (!base.some((m) => m.route === 'MasterDataNasabah')) extra.push(M_MASTER_NASABAH)
	if (!base.some((m) => m.route === 'TargetRealisasi')) extra.push(M_TARGET)
	if (isDeviasiDirector.value && !base.some((m) => m.route === 'Deviasi')) extra.push(M_DEVIASI)
	// Director punya read/write STPL Unit Hilang di permission doctype.
	if (!base.some((m) => m.route === 'StplUnitHilang')) extra.push(M_STPL_HILANG)
	return [...base, ...extra]
}

// Deviasi untuk Director dibatasi ke user tertentu saja (bukan semua Director),
// karena akses Deviasi diberikan per orang. Role Director punya read Deviasi di
// Custom DocPerm, jadi pembatasan di sini murni soal tampil/tidaknya tile.
// Tambahkan email di sini bila ada Director lain yang perlu akses.
const DEVIASI_DIRECTOR_USERS = ['erwanpi5555@gmail.com']
const isDeviasiDirector = computed(
	() => roles.value.includes('Director') && DEVIASI_DIRECTOR_USERS.includes(currentUser.user),
)

// Master Data Nasabah untuk user tertentu di luar yang sudah dapat lewat jalur
// role (Director/Pimcab/Administrator) — mis. Manager Coll yang perlu lihat data
// nasabah. Doctype-nya sudah read untuk role 'All User' di Custom DocPerm, jadi
// pembatasan di sini murni soal tampil/tidaknya tile.
// Tambahkan email di sini bila ada user lain yang perlu akses.
const MASTER_NASABAH_USERS = ['tiopan191185@gmail.com']
function withMasterNasabahForUser(base) {
	if (!MASTER_NASABAH_USERS.includes(currentUser.user)) return base
	if (base.some((m) => m.route === 'MasterDataNasabah')) return base
	return [...base, M_MASTER_NASABAH]
}

// Administrator → SEMUA menu yang ada.
const MENU_ALL = [
	M_RESI,
	M_DATA_PENGAJUAN,
	M_DISKRESI,
	M_FID_FPD,
	M_DASHBOARD,
	M_LIST_MARKETING,
	M_MASTER_NASABAH,
	M_DEVIASI,
	M_BSTK,
	M_TTS,
	M_STPL_HILANG,
	M_REQUEST_DOK_COLL,
	M_MOTOR_TARIKAN,
	M_STOCKOUT_MOTOR,
	M_INVOICE_MOTOR,
	M_CUTI,
	M_PENYESUAIAN_CUTI,
	M_KETERLAMBATAN,
	...(MASTER_KARYAWAN_TAMPIL ? [M_MASTER_KARYAWAN] : []),
	{ name: 'payroll', label: 'Payroll' },
	{ name: 'transactions', label: 'Transactions' },
	{ name: 'payment', label: 'Payment' },
	{ name: 'timesheet', label: 'Timesheet' },
	{ name: 'quotation', label: 'Quotation' },
	{ name: 'attendreq', label: 'Attend Req' },
	{ name: 'shiftreq', label: 'Shift Req' },
	...MENU_TARGET_REALISASI,
]

const isAdmin = computed(
	() =>
		currentUser.user === 'Administrator' ||
		(currentUser.roles || []).includes('System Manager'),
)

// Peran yang absensinya hanya informasi: jamnya tidak dikoreksi lewat alur
// keterlambatan, jadi mereka tidak pernah mengisi alasan dan tile-nya tidak
// perlu ada. Daftarnya sama dengan pengecualian di server (ROLE_PUNCAK di
// juragan/hr/atasan.py) supaya app dan backend tidak bisa berbeda pendapat.
const ROLE_TANPA_KETERLAMBATAN = [
	'Pimcab',
	'Manager Ops',
	'Manager Finance',
	'Manager Coll',
	'Manager Collection',
	'Director',
]
const tanpaKeterlambatan = computed(() =>
	ROLE_TANPA_KETERLAMBATAN.some((r) => roles.value.includes(r)),
)

const hasManagerOpsRole = computed(() => roles.value.includes('Manager Ops'))

const hasManagerFinanceRole = computed(() => roles.value.includes('Manager Finance'))

const hasOwnerRole = computed(() => roles.value.includes('Owner'))

// Resi dibatasi: HANYA Administrator/System Manager (isAdmin) dan role Manager.
// Dipakai collMenu (Manager Coll) dan wrapper withResi untuk jalur menu lain.
const MANAGER_ROLES = ['Manager Ops', 'Manager Finance', 'Manager Coll', 'Manager Collection']
const isManager = computed(() => MANAGER_ROLES.some((role) => roles.value.includes(role)))

// Master Karyawan → saringan role mengikuti permission doctype apa adanya:
// System Manager, HR Manager, HR User (read/write/create) dan Employee (read).
// Saat ini tidak terpakai karena tile-nya disembunyikan lewat
// MASTER_KARYAWAN_TAMPIL; dibiarkan utuh agar saringannya kembali berlaku
// begitu saklar itu dinyalakan lagi.
const MASTER_KARYAWAN_ROLES = ['System Manager', 'HR Manager', 'HR User', 'Employee']
function withMasterKaryawan(base) {
	if (!MASTER_KARYAWAN_TAMPIL) return base
	if (!MASTER_KARYAWAN_ROLES.some((role) => roles.value.includes(role))) return base
	if (base.some((m) => m.route === 'MasterKaryawan')) return base
	return [...base, M_MASTER_KARYAWAN]
}

// Mengikuti permission doctype Penyesuaian Cuti; peran lain tidak akan bisa
// membuka isinya, jadi tile-nya disembunyikan alih-alih menyesatkan.
const PENYESUAIAN_CUTI_ROLES = ['System Manager', 'HR Manager', 'HR User']
function withPenyesuaianCuti(base) {
	if (!PENYESUAIAN_CUTI_ROLES.some((role) => roles.value.includes(role))) return base
	if (base.some((m) => m.route === 'PenyesuaianCuti')) return base
	return [...base, M_PENYESUAIAN_CUTI]
}

// Section kartu geser dashboard muncul bila user berhak atas SETIDAKNYA satu
// kartunya; kartu mana yang dirender ditentukan komponennya sendiri dengan
// gerbang yang sama (config/dashboards.js). `ready` ikut dicek agar section
// tidak berkedip muncul-hilang saat role masih dimuat.
const tampilkanDashboard = computed(
	() => ready.value && punyaDashboard(currentUser.user, roles.value),
)

function withResi(base) {
	if (!isManager.value) return base
	if (base.some((m) => m.route === 'Resi')) return base
	return [...base, M_RESI]
}

// Cuti berlaku untuk SEMUA karyawan tanpa kecuali — tidak disaring role seperti
// wrapper lain di sekitarnya. Halamannya sendiri yang menyesuaikan isi: karyawan
// biasa hanya melihat pengajuannya, atasan & HR mendapat tab persetujuan.
function withCuti(base) {
	if (base.some((m) => m.route === 'Cuti')) return base
	return [...base, M_CUTI]
}

// Keterlambatan berlaku untuk karyawan yang memang mengisi alasan telatnya.
// Halamannya hanya menampilkan catatan milik sendiri.
//
// Filter dijalankan lebih dulu, bukan sekadar "jangan tambah": beberapa daftar
// tetap (MENU_ALL) sudah memuat tile ini, jadi menahan penambahan saja tidak
// cukup untuk menyembunyikannya.
function withKeterlambatan(base) {
	if (tanpaKeterlambatan.value) return base.filter((m) => m.route !== 'Keterlambatan')
	if (base.some((m) => m.route === 'Keterlambatan')) return base
	return [...base, M_KETERLAMBATAN]
}

// Antrean approval hanya untuk Director — wewenangnya dijaga ulang di server,
// ini sekadar menampilkan pintunya pada orang yang memang memilikinya.
function withApprovalKeterlambatan(base) {
	if (!roles.value.includes('Director')) return base
	if (base.some((m) => m.route === 'KeterlambatanKetua')) return base
	return [...base, M_APPROVAL_KETERLAMBATAN]
}

const todoMenu = computed(() => {
	if (!ready.value) return []
	let base
	if (isAdmin.value) base = MENU_ALL
	// Manager Ops → daftar tetap 6 menu, dikembalikan apa adanya (tanpa wrapper
	// tambahan) supaya aksesnya benar-benar terbatas pada MENU_MANAGER_OPS.
	else if (hasManagerOpsRole.value)
		return withApprovalKeterlambatan(withKeterlambatan(withCuti(MENU_MANAGER_OPS)))
	// Manager Finance → daftar tetap 8 menu, juga dikembalikan apa adanya.
	else if (hasManagerFinanceRole.value)
		return withApprovalKeterlambatan(withKeterlambatan(withCuti(MENU_MANAGER_FINANCE)))
	// Owner → daftar tetap 6 menu (dicek sebelum role *Coll* agar Owner yang
	// kebetulan juga punya role Coll tetap memakai daftar Owner).
	else if (hasOwnerRole.value)
		return withApprovalKeterlambatan(withKeterlambatan(withCuti(MENU_OWNER)))
	// Role berunsur "coll" → menu Target & Realisasi + tile khusus per role
	// (Deviasi utk Manager Coll; BSTK/TTS utk Field/Desk/Admin Coll).
	else if (hasCollRole.value) base = collMenu.value
	else base = MENU_BY_ROLE[department.value?.key] || MENU_DEFAULT
	// Wrapper di bawah hanya berlaku untuk role selain Manager Ops/Manager
	// Finance (keduanya sudah return lebih awal dengan daftar tetap).
	// Tebus Motor & Request AYDA → hanya Director/Manager Coll/Manager Finance.
	// Motor Tarikan → hanya Manager Finance/Director/Staff Finance (read doctype).
	// Stock Out Motor & Invoice Motor → hanya Manager Finance/Director (read doctype).
	// Director → tambahan Master Data Nasabah & Target dan Realisasi.
	// Resi → hanya role Manager (Administrator sudah lewat MENU_ALL).
	// Terakhir: Master Data Nasabah untuk user yang di-allowlist per orang.
	// Dirangkai berurutan supaya jelas terbaca, bukan bersarang dalam-dalam.
	return [
		withTebusAyda,
		withMotorTarikan,
		withStockOutMotor,
		withInvoiceMotor,
		withDirectorExtras,
		withResi,
		withMasterNasabahForUser,
		withMasterKaryawan,
		withPenyesuaianCuti,
		withCuti,
		withKeterlambatan,
		withApprovalKeterlambatan,
	].reduce((menu, tambahkan) => tambahkan(menu), base)
})

// Layout grid menu adaptif terhadap jumlah item — SAMA untuk semua role
// (termasuk Coll): menu tidak pernah lebih tinggi dari 3 baris.
//  - >9  → maksimal 3 baris → scroll horizontal (grid-flow-col)
//  - 5–9 → 3 kolom penuh lebar, mengisi ke samping dulu (5 = 3+2, 6 = 3+3,
//          9 = 3×3) — tanpa ruang kosong di sisi samping
//  - 4   → 2 kolom (2×2)
//  - ≤3  → satu baris memanjang (N kolom)
const menuScroll = computed(() => todoMenu.value.length > 9)
const menuCols = computed(() => {
	const n = todoMenu.value.length
	if (n >= 5) return 3
	if (n === 4) return 2
	return n || 1
})

// Salam menyesuaikan waktu lokal (Good Morning / Afternoon / Evening).
const greeting = computed(() => {
	const h = new Date().getHours()
	if (h < 12) return 'Good Morning'
	if (h < 18) return 'Good Afternoon'
	return 'Good Evening'
})
</script>
