/**
 * Integrasi push notification OneSignal.
 *
 * Semua fungsi di berkas ini hanya berjalan saat portal dibuka DI DALAM
 * aplikasi native (Capacitor). Saat portal dibuka di browser biasa,
 * setiap fungsi langsung berhenti tanpa melakukan apa pun.
 */

// App ID dari dashboard OneSignal (Settings → Keys & IDs).
// Nilai ini publik (bukan rahasia), jadi boleh ditulis langsung di sini.

const ONESIGNAL_APP_ID = 'c01de045-9b9b-4850-891d-dabf675bc369'

function isNativeApp() {
	return !!(
		window.Capacitor &&
		window.Capacitor.isNativePlatform &&
		window.Capacitor.isNativePlatform()
	)
}

function getOneSignal() {
	return (window.plugins && window.plugins.OneSignal) || null
}

function waitForOneSignal(timeoutMs = 5000) {
	return new Promise((resolve) => {
		const start = Date.now()
		const timer = setInterval(() => {
			const os = getOneSignal()
			if (os || Date.now() - start > timeoutMs) {
				clearInterval(timer)
				resolve(os)
			}
		}, 100)
	})
}

let initialized = false

export async function initPush(router) {
	if (!isNativeApp() || initialized) return
	const OneSignal = await waitForOneSignal()
	if (!OneSignal) return
	initialized = true

	OneSignal.initialize(ONESIGNAL_APP_ID)

	OneSignal.Notifications.requestPermission(true)

	OneSignal.Notifications.addEventListener('click', (event) => {
		const data = (event.notification && event.notification.additionalData) || {}
		if (data.document_type === 'Data Pengajuan' && data.document_name) {
			router.push({
				name: 'DataPengajuanDetail',
				params: { name: data.document_name },
			})
		} else if (data.document_type) {
			// Doctype lain (mis. Deviasi, SPPU Collector) belum punya halaman
			// detail di portal → buka daftar notifikasi sebagai tujuan bawaan.
			router.push({ name: 'Notifications' })
		}
	})
}

export async function pushLogin(email) {
	if (!isNativeApp() || !email) return
	const OneSignal = await waitForOneSignal()
	if (OneSignal) OneSignal.login(email)
}

export async function pushLogout() {
	if (!isNativeApp()) return
	const OneSignal = await waitForOneSignal()
	if (OneSignal) OneSignal.logout()
}
