<template>
	<Teleport to="body">
		<!-- Backdrop: fade masuk/keluar -->
		<Transition
			enter-active-class="transition-opacity duration-200"
			enter-from-class="opacity-0"
			leave-active-class="transition-opacity duration-150"
			leave-to-class="opacity-0"
		>
			<div
				v-if="open"
				class="fixed inset-0 z-[80] flex items-end justify-center bg-black/50 sm:items-center sm:p-4"
				:style="viewportStyle"
				@click.self="close"
			>
				<!-- Panel: slide naik dari bawah -->
				<Transition
					appear
					enter-active-class="transition-transform duration-200 ease-out"
					enter-from-class="translate-y-full"
					leave-active-class="transition-transform duration-150 ease-in"
					leave-to-class="translate-y-full"
				>
					<div
						v-if="open"
						class="flex max-h-[92dvh] w-full max-w-3xl flex-col overflow-hidden rounded-t-2xl bg-ui-surface shadow-2xl sm:rounded-2xl"
						:style="panelStyle"
					>
						<!-- Header -->
						<div
							class="flex shrink-0 items-center justify-between gap-3 border-b border-ui-line-gray-100 px-5 py-3.5"
						>
							<div class="min-w-0">
								<h2 class="truncate text-lg font-semibold text-primary pb-2">
									Cek Tunggakan
								</h2>
								<p class="truncate text-xs text-ink-gray-5">
									{{
										tunggakanRes.data?.nasabah?.nama_nasabah ||
										'Masukkan No Perjanjian'
									}}
								</p>
							</div>
							<button
								type="button"
								class="-mr-1 flex h-9 w-9 shrink-0 items-center justify-center rounded-md text-ui-ink-gray-400 transition hover:bg-ui-surface-gray-100 hover:text-ui-ink-gray-600"
								aria-label="Tutup"
								@click="close"
							>
								<svg
									xmlns="http://www.w3.org/2000/svg"
									viewBox="0 0 24 24"
									class="h-5 w-5"
									fill="none"
									stroke="currentColor"
									stroke-width="2"
									stroke-linecap="round"
									stroke-linejoin="round"
								>
									<path d="M18 6 6 18" />
									<path d="m6 6 12 12" />
								</svg>
							</button>
						</div>

						<!-- Body -->
						<div class="min-h-0 flex-1 overflow-y-auto px-5 py-4">
							<!-- Field No Perjanjian (autocomplete, ala Link Frappe) -->
							<div class="relative mb-4">
								<label class="mb-1 block text-xs font-medium text-ink-gray-5"
									>No Perjanjian</label
								>
								<input
									v-model="query"
									type="text"
									autocomplete="off"
									placeholder="Ketik No Perjanjian / nama nasabah…"
									class="w-full rounded-lg border border-ui-line-gray-300 px-3 py-2 text-base text-ink-gray-8 focus:border-primary focus:outline-none focus:ring-1 focus:ring-primary"
									@input="onInput"
									@focus="showSuggest = true"
									@blur="onBlur"
								/>
								<!-- Dropdown saran -->
								<div
									v-if="
										showSuggest &&
										(searchRes.loading || suggestions.length || query.trim())
									"
									class="absolute z-10 mt-1 max-h-60 w-full overflow-y-auto rounded-lg border border-ui-line-gray-200 bg-ui-surface shadow-lg"
								>
									<div
										v-if="searchRes.loading"
										class="px-3 py-2 text-xs text-ink-gray-5"
									>
										Mencari…
									</div>
									<template v-else>
										<button
											v-for="s in suggestions"
											:key="s.value"
											type="button"
											class="block w-full px-3 py-2 text-left hover:bg-ui-surface-gray-50"
											@mousedown.prevent="pilih(s)"
										>
											<span
												class="block text-sm font-medium text-ink-gray-8"
												>{{ s.value }}</span
											>
											<span
												v-if="s.nama"
												class="block text-xs text-ink-gray-5"
												>{{ s.nama }}</span
											>
										</button>
										<div
											v-if="!suggestions.length && query.trim()"
											class="px-3 py-2 text-xs text-ink-gray-5"
										>
											Tidak ditemukan.
										</div>
									</template>
								</div>
							</div>

							<!-- Loading -->
							<div
								v-if="tunggakanRes.loading"
								class="flex flex-col items-center justify-center gap-3 py-16 text-center"
							>
								<svg
									class="h-7 w-7 animate-spin text-primary"
									viewBox="0 0 24 24"
									fill="none"
									xmlns="http://www.w3.org/2000/svg"
								>
									<circle
										cx="12"
										cy="12"
										r="9"
										stroke="currentColor"
										stroke-width="2"
										stroke-opacity="0.25"
									/>
									<path
										d="M21 12a9 9 0 0 0-9-9"
										stroke="currentColor"
										stroke-width="2"
										stroke-linecap="round"
									/>
								</svg>
								<p class="text-xs text-ink-gray-5">Mengambil data tunggakan…</p>
							</div>

							<!-- Error -->
							<div
								v-else-if="tunggakanError"
								class="rounded-lg border border-ui-line-red-200 bg-ui-surface-red-50 px-4 py-3 text-xs text-ui-ink-red-700"
							>
								{{ tunggakanError }}
							</div>

							<!-- Tidak ada No Rekening Kredit -->
							<div
								v-else-if="tunggakanRes.data && !tunggakanRes.data.has_rekening"
								class="rounded-lg border border-ui-line-amber-200 bg-ui-surface-amber-50 px-4 py-3 text-xs text-ui-ink-amber-800"
							>
								Nasabah ini tidak memiliki No Rekening Kredit.
							</div>

							<!-- Konten -->
							<template v-else-if="tunggakanRes.data">
								<!-- Info nasabah -->
								<div
									class="mb-4 grid grid-cols-1 gap-x-6 gap-y-2.5 sm:grid-cols-2"
								>
									<div
										v-for="info in nasabahInfo"
										:key="info.label"
										class="flex items-start justify-between gap-3 border-b border-ui-line-gray-50 pb-2"
									>
										<span class="shrink-0 text-xs text-ink-gray-5">{{
											info.label
										}}</span>
										<span
											class="min-w-0 truncate text-right text-xs font-medium text-ink-gray-8"
											>{{ info.value }}</span
										>
									</div>
								</div>

								<!-- Tabel angsuran menunggak -->
								<div class="overflow-x-auto rounded-lg border border-ui-line-gray-200">
									<table class="w-full min-w-[560px] text-xs">
										<thead>
											<tr
												class="border-b border-ui-line-gray-200 bg-ui-surface-gray-50 text-left text-ink-gray-5"
											>
												<th class="px-3 py-2 font-medium">Angsuran Ke</th>
												<th class="px-3 py-2 font-medium">Tgl Angsuran</th>
												<th class="px-3 py-2 text-right font-medium">
													Total Angsuran
												</th>
												<th class="px-3 py-2 text-center font-medium">
													JHT
												</th>
												<th class="px-3 py-2 font-medium">Tgl Bayar</th>
												<th class="px-3 py-2 font-medium">Status</th>
											</tr>
										</thead>
										<tbody class="divide-y divide-ui-line-gray-100">
											<tr v-for="(row, i) in tunggakanRows" :key="i">
												<td class="px-3 py-2 text-ink-gray-8">
													{{ row.No || '-' }}
												</td>
												<td class="px-3 py-2 text-ink-gray-7">
													{{ row.Tgl_Jatuh_Tempo || '-' }}
												</td>
												<td
													class="px-3 py-2 text-right font-medium text-ink-gray-8"
												>
													{{ fmtRp(row.J_Total) }}
												</td>
												<td class="px-3 py-2 text-center">
													<span
														class="inline-flex min-w-[28px] justify-center rounded-full bg-ui-surface-red-100 px-1.5 py-0.5 text-[11px] font-semibold text-ui-ink-red-700"
													>
														{{ row.Hari_Telat || '0' }}
													</span>
												</td>
												<td class="px-3 py-2 text-ink-gray-7">
													{{ row.Tgl_Lunas_Full || '-' }}
												</td>
												<td class="px-3 py-2">
													<span
														class="inline-flex rounded-full bg-ui-surface-amber-100 px-2 py-0.5 text-[11px] font-medium text-ui-ink-amber-800"
													>
														{{ row.Status || '-' }}
													</span>
												</td>
											</tr>
											<tr v-if="!tunggakanRows.length">
												<td
													colspan="6"
													class="px-3 py-6 text-center text-ink-gray-5"
												>
													Tidak ada tunggakan.
												</td>
											</tr>
										</tbody>
									</table>
								</div>

								<!-- Ringkasan -->
								<div class="mt-4 rounded-lg border border-ui-line-gray-200 bg-ui-surface-gray-50 p-4">
									<div class="grid grid-cols-1 gap-x-6 gap-y-2 sm:grid-cols-2">
										<div
											v-for="s in ringkasan"
											:key="s.label"
											class="flex items-center justify-between gap-3"
										>
											<span class="text-xs text-ink-gray-5">{{
												s.label
											}}</span>
											<span class="text-xs font-medium text-ink-gray-8">{{
												s.value
											}}</span>
										</div>
									</div>
									<div
										class="mt-3 flex items-center justify-between gap-3 border-t border-ui-line-gray-200 pt-3"
									>
										<span class="text-sm font-semibold text-ink-gray-7"
											>Total Hutang</span
										>
										<span class="text-base font-bold text-primary">{{
											fmtRp(tunggakanRes.data.rincian?.total_hutang)
										}}</span>
									</div>
								</div>

								<p class="mt-3 text-right text-[11px] text-ink-gray-4">
									Dicek pada {{ nowStr() }}
								</p>
							</template>

							<!-- Belum ada yang dipilih -->
							<div v-else class="py-14 text-center text-xs text-ink-gray-4">
								Pilih No Perjanjian untuk melihat tunggakan.
							</div>
						</div>

						<!-- Footer (ukuran tombol disamakan dgn tombol aksi Data Pengajuan).
						     Modal ini menempel ke tepi bawah layar (items-end + rounded-t),
						     jadi padding bawahnya harus menghitung safe-area — kalau tidak,
						     tombol Cari/Tutup tertutup taskbar/gesture bar perangkat. -->
						<div class="flex shrink-0 border-t border-ui-line-gray-100 px-5 py-3 sheet-footer">
							<!-- Sebelum ada hasil: tombol Cari full-width -->
							<button
								v-if="!tunggakanRes.data"
								type="button"
								:disabled="!query.trim() || tunggakanRes.loading"
								class="flex w-full items-center justify-center gap-2 rounded-full bg-primary py-3 text-sm font-semibold text-ui-onPrimary shadow-sm transition active:scale-[0.99] disabled:cursor-not-allowed disabled:opacity-50"
								@click="cari"
							>
								{{ tunggakanRes.loading ? 'Mencari…' : 'Cari' }}
							</button>
							<!-- Setelah ada hasil: tombol Tutup full-width (biru) -->
							<button
								v-else
								type="button"
								class="flex w-full items-center justify-center gap-2 rounded-full bg-primary py-3 text-sm font-semibold text-ui-onPrimary shadow-sm transition active:scale-[0.99]"
								@click="close"
							>
								Tutup
							</button>
						</div>
					</div>
				</Transition>
			</div>
		</Transition>
	</Teleport>
</template>

<script setup>
import { ref, computed, watch, onMounted, onBeforeUnmount } from 'vue'
import { createResource } from 'frappe-ui'

const props = defineProps({
	open: { type: Boolean, default: false },
})
const emit = defineEmits(['update:open'])
function close() {
	emit('update:open', false)
}

// ===== Tinggi viewport saat keyboard terbuka =====
// Di Android, membuka keyboard TIDAK selalu mengecilkan viewport layout, jadi
// 100dvh (dan max-h-[92dvh]) tetap seukuran layar penuh. Akibatnya bagian bawah
// modal — termasuk dropdown saran — digambar di belakang keyboard dan tidak bisa
// dijangkau: body modal pun tidak bisa di-scroll karena isinya memang muat di
// dalam tinggi yang (salah) dihitung itu. visualViewport melaporkan tinggi yang
// BENAR-BENAR terlihat, jadi tinggi overlay & panel diikatkan ke sana.
const viewportH = ref(0)
function syncViewport() {
	const vv = window.visualViewport
	viewportH.value = vv ? Math.round(vv.height) : 0
}
const viewportStyle = computed(() => (viewportH.value ? { height: viewportH.value + 'px' } : {}))
const panelStyle = computed(() =>
	viewportH.value ? { maxHeight: Math.round(viewportH.value * 0.92) + 'px' } : {}
)
onMounted(() => {
	syncViewport()
	window.visualViewport?.addEventListener('resize', syncViewport)
	window.visualViewport?.addEventListener('scroll', syncViewport)
})
onBeforeUnmount(() => {
	window.visualViewport?.removeEventListener('resize', syncViewport)
	window.visualViewport?.removeEventListener('scroll', syncViewport)
})

const query = ref('')
const selected = ref('') // No Perjanjian terpilih
const showSuggest = ref(false)

// ===== Autocomplete No Perjanjian (Link-style) =====
const searchRes = createResource({
	url: 'juragan.api.portal.tunggakan.search_perjanjian',
	method: 'GET',
	auto: false,
	makeParams: () => ({ txt: query.value.trim() }),
})
const suggestions = computed(() => (Array.isArray(searchRes.data) ? searchRes.data : []))

let debounce = null
function onInput() {
	selected.value = ''
	showSuggest.value = true
	// Edit field lagi → buang hasil lama supaya tombol Cari muncul kembali.
	tunggakanRes.reset?.()
	clearTimeout(debounce)
	if (!query.value.trim()) return
	debounce = setTimeout(() => searchRes.fetch(), 250)
}
function onBlur() {
	// Delay agar klik saran sempat terproses sebelum dropdown ditutup.
	setTimeout(() => (showSuggest.value = false), 150)
}
function pilih(s) {
	// Hanya isi field — tidak langsung cek. Pencarian dijalankan via tombol "Cari".
	query.value = s.value
	selected.value = s.value
	showSuggest.value = false
}
// Tombol "Cari": baru ambil & tampilkan data tunggakan.
function cari() {
	const v = query.value.trim()
	if (!v) return
	selected.value = v
	showSuggest.value = false
	tunggakanRes.fetch()
}

// ===== Cek Tunggakan (bentuk data sama dengan modal FID/FPD) =====
const tunggakanRes = createResource({
	url: 'juragan.api.portal.tunggakan.get_tunggakan_by_perjanjian',
	method: 'GET',
	auto: false,
	makeParams: () => ({ no_perjanjian: selected.value }),
})
const tunggakanError = computed(() => {
	const e = tunggakanRes.error
	if (!e) return ''
	return e?.messages?.[0] || e?.message || 'Gagal mengambil data tunggakan.'
})

// Hanya baris tunggakan (sembunyikan Lunas / Lunas dipercepat / kosong) — sama desk.
const tunggakanRows = computed(() => {
	const rows = tunggakanRes.data?.rincian?.tabel_angsuran
	if (!Array.isArray(rows)) return []
	return rows.filter((row) => {
		const st = String(row.Status || '')
			.trim()
			.toLowerCase()
		return !['lunas', 'lunas (dipercepat)', '-', ''].includes(st)
	})
})
// Info header nasabah (field & urutan sama desk).
const nasabahInfo = computed(() => {
	const n = tunggakanRes.data?.nasabah || {}
	return [
		{ label: 'Nama Nasabah', value: n.nama_nasabah || '-' },
		{ label: 'Nama Kendaraan', value: `${n.merk || ''} ${n.model || ''}`.trim() || '-' },
		{ label: 'Plafond', value: fmtRp(n.pinjaman) },
		{ label: 'No. Polisi', value: n.nopol || '-' },
		{ label: 'Jangka Waktu', value: n.tenor ? `${n.tenor} Bulan` : '-' },
		{
			label: 'Tanggal Pencairan',
			value: n.tanggal_pencairan ? formatDate(n.tanggal_pencairan) : '-',
		},
	]
})
// Ringkasan finansial (semua field desk; Total Hutang ditonjolkan terpisah).
const ringkasan = computed(() => {
	const r = tunggakanRes.data?.rincian || {}
	return [
		{ label: 'Total Denda', value: fmtRp(r.total_denda) },
		{ label: 'Sisa Pokok', value: fmtRp(r.sisa_pokok) },
		{ label: 'Sisa Bunga', value: fmtRp(r.sisa_bunga) },
		{ label: 'Sisa Admin', value: fmtRp(r.sisa_admin) },
		{ label: 'Total Sisa Angsuran', value: fmtRp(r.total_sisa_angsuran) },
		{ label: 'Saldo Tabungan', value: fmtRp(r.saldo_tabungan) },
	]
})

// Format angka → "Rp 1.234.567" (nilai bisa string/number dari n8n).
function fmtRp(v) {
	let n = typeof v === 'string' ? parseFloat(v.replace(/,/g, '')) : Number(v)
	if (!Number.isFinite(n)) n = 0
	return 'Rp ' + new Intl.NumberFormat('id-ID', { maximumFractionDigits: 0 }).format(n)
}
// "YYYY-MM-DD" → "DD-MM-YYYY".
function formatDate(v) {
	if (!v) return '-'
	const s = String(v).slice(0, 10)
	const [y, m, d] = s.split('-')
	return d && m && y ? `${d}-${m}-${y}` : s
}
function nowStr() {
	const d = new Date()
	const p = (x) => String(x).padStart(2, '0')
	return `${p(d.getDate())}-${p(d.getMonth() + 1)}-${d.getFullYear()} ${p(d.getHours())}:${p(
		d.getMinutes()
	)}`
}

// Reset state tiap kali modal dibuka → mulai bersih.
watch(
	() => props.open,
	(v) => {
		if (v) {
			query.value = ''
			selected.value = ''
			showSuggest.value = false
			searchRes.reset?.()
			tunggakanRes.reset?.()
		}
	}
)
</script>
